"use client";
import {useEffect,useRef,useState} from "react";

const HEART_SRC="data:image/jpeg;base64,";

function cubic(a,b,c,d,t){
  const m=1-t;
  return m*m*m*a+3*m*m*t*b+3*m*t*t*c+t*t*t*d;
}
function flowPoint(t,w,h){
  return {
    x:cubic(.665,.635,.615,.565,t)*w,
    y:cubic(.335,.405,.575,.735,t)*h
  };
}

const SAMPLE_CELLS=[
  [.642,.388,.018,.027],
  [.655,.432,.017,.025],
  [.637,.487,.019,.028],
  [.622,.544,.018,.027],
  [.616,.598,.018,.026],
  [.596,.645,.019,.028],
  [.575,.690,.018,.026]
];

export default function HeartBloodOverlay(){
  const canvasRef=useRef(null);
  const imageRef=useRef(null);
  const rafRef=useRef(0);
  const startRef=useRef(0);
  const [playing,setPlaying]=useState(true);
  const [speed,setSpeed]=useState(1);

  useEffect(()=>{
    const img=imageRef.current;
    const canvas=canvasRef.current;
    if(!img||!canvas) return;

    const setup=()=>{
      canvas.width=img.naturalWidth||1536;
      canvas.height=img.naturalHeight||1024;
    };
    if(img.complete) setup(); else img.addEventListener("load",setup,{once:true});

    const draw=(now)=>{
      const ctx=canvas.getContext("2d");
      const w=canvas.width,h=canvas.height;
      if(!w||!h){rafRef.current=requestAnimationFrame(draw);return;}
      if(!startRef.current) startRef.current=now;
      const elapsed=(now-startRef.current)/1000;
      ctx.clearRect(0,0,w,h);

      // Hide the static reference cells only inside the tested flow corridor.
      // This matte is deliberately local, soft and perspective-aware.
      ctx.save();
      ctx.lineCap="round";
      ctx.lineJoin="round";
      ctx.beginPath();
      const p0=flowPoint(0,w,h);
      ctx.moveTo(p0.x,p0.y);
      for(let i=1;i<=30;i++){
        const p=flowPoint(i/30,w,h);
        ctx.lineTo(p.x,p.y);
      }
      const g=ctx.createLinearGradient(.67*w,.34*h,.56*w,.74*h);
      g.addColorStop(0,"rgba(72,7,10,.42)");
      g.addColorStop(.45,"rgba(84,5,8,.34)");
      g.addColorStop(1,"rgba(54,2,4,.26)");
      ctx.strokeStyle=g;
      ctx.lineWidth=w*.032;
      ctx.shadowColor="rgba(145,10,12,.18)";
      ctx.shadowBlur=w*.008;
      ctx.stroke();
      ctx.restore();

      // Integrating glow: follows exactly the same anatomical corridor.
      ctx.save();
      ctx.beginPath();
      ctx.moveTo(p0.x,p0.y);
      for(let i=1;i<=28;i++){
        const p=flowPoint(i/28,w,h);
        ctx.lineTo(p.x,p.y);
      }
      ctx.strokeStyle="rgba(236,47,40,.16)";
      ctx.lineWidth=w*.012;
      ctx.lineCap="round";
      ctx.shadowColor="rgba(255,44,35,.28)";
      ctx.shadowBlur=w*.012;
      ctx.stroke();
      ctx.restore();

      // Reuse exact pixel crops from the cinematic source itself.
      // No synthetic blood-cell drawing is used.
      const phase=playing ? elapsed*0.12*speed : 0;
      SAMPLE_CELLS.forEach((s,i)=>{
        const t=(phase+i/SAMPLE_CELLS.length)%1;
        const p=flowPoint(t,w,h);
        const perspective=.72+.34*t;
        const base=Math.max(18,w*.021);
        const size=base*perspective;
        const [sx,sy,sw,sh]=s;
        const srcX=sx*img.naturalWidth;
        const srcY=sy*img.naturalHeight;
        const srcW=sw*img.naturalWidth;
        const srcH=sh*img.naturalHeight;
        const wobble=Math.sin((elapsed*1.5+i)*1.7)*w*.0018;

        ctx.save();
        ctx.translate(p.x+wobble,p.y);
        ctx.rotate(Math.sin((t+i)*5.2)*.12);
        ctx.beginPath();
        ctx.ellipse(0,0,size*.55,size*.46,0,0,Math.PI*2);
        ctx.clip();
        ctx.filter="saturate(1.12) contrast(1.05)";
        ctx.shadowColor="rgba(255,70,55,.26)";
        ctx.shadowBlur=size*.45;
        ctx.drawImage(img,srcX,srcY,srcW,srcH,-size*.58,-size*.52,size*1.16,size*1.04);
        ctx.restore();

        // tiny optical highlight to keep the crop integrated while moving
        ctx.save();
        ctx.globalAlpha=.14;
        ctx.fillStyle="#ffd7c7";
        ctx.beginPath();
        ctx.ellipse(p.x-size*.14,p.y-size*.12,size*.12,size*.07,-.35,0,Math.PI*2);
        ctx.fill();
        ctx.restore();
      });

      rafRef.current=requestAnimationFrame(draw);
    };
    rafRef.current=requestAnimationFrame(draw);
    return ()=>cancelAnimationFrame(rafRef.current);
  },[playing,speed]);

  return <main style={{minHeight:"100vh",background:"#020812",display:"grid",placeItems:"center",padding:0}}>
    <section style={{position:"relative",width:"min(100vw,1536px)",aspectRatio:"3/2",overflow:"hidden",background:"#020812"}}>
      <img
        ref={imageRef}
        src={HEART_SRC}
        alt="Cinematic anatomical heart reference"
        style={{display:"block",width:"100%",height:"100%",objectFit:"contain",userSelect:"none"}}
      />
      <canvas
        ref={canvasRef}
        aria-label="Animated blood-flow overlay"
        style={{position:"absolute",inset:0,width:"100%",height:"100%",pointerEvents:"none"}}
      />
      <div style={{
        position:"absolute",left:"2.2%",top:"2.3%",zIndex:4,
        display:"flex",alignItems:"center",gap:8,padding:"7px 9px",
        border:"1px solid rgba(255,255,255,.14)",borderRadius:999,
        background:"rgba(4,9,16,.72)",backdropFilter:"blur(10px)",
        boxShadow:"0 8px 30px rgba(0,0,0,.26)"
      }}>
        <button onClick={()=>setPlaying(v=>!v)} style={{
          border:"1px solid rgba(236,72,60,.45)",borderRadius:999,
          background:"rgba(112,17,18,.72)",color:"#fff",padding:"6px 11px",
          fontSize:12,fontWeight:750,cursor:"pointer"
        }}>{playing?"إيقاف":"تشغيل"}</button>
        <input aria-label="سرعة تدفق الدم" type="range" min=".55" max="1.65" step=".05"
          value={speed} onChange={e=>setSpeed(Number(e.target.value))}
          style={{width:92,accentColor:"#e84b43"}}/>
        <span style={{fontSize:10,color:"#f5cbc7",whiteSpace:"nowrap"}}>Blood flow × {speed.toFixed(2)}</span>
      </div>
      <div style={{
        position:"absolute",right:"2.2%",top:"2.6%",zIndex:4,
        color:"#f5ddd8",fontSize:11,letterSpacing:".03em",
        padding:"7px 10px",borderRadius:999,
        background:"rgba(5,10,17,.64)",border:"1px solid rgba(255,255,255,.1)",
        backdropFilter:"blur(8px)"
      }}>POC · exact-image blood sprites</div>
    </section>
  </main>;
}
